"""Generate the verified numbers for the Phase 1-3 exploratory report from the raw verdict records.
Every figure the write-up may cite is computed here and written to phase23-report/RESULTS.md (and RESULTS.json).
Usage (from the repository root): python analysis/phase23.py
"""
import json, glob, os, sys, collections, random, re
HERE = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.dirname(HERE); H = os.path.join(ROOT, "harness")
sys.path.insert(0, HERE); from pilot import price_for
OUT = os.path.join(ROOT, "phase23-report"); os.makedirs(OUT, exist_ok=True)
B = 2000

def boot(pairs, seed=2):
    rnd = random.Random(seed); n = len(pairs)
    ds = sorted(sum(a - b for a, b in [rnd.choice(pairs) for _ in range(n)]) / n for _ in range(B))
    d = sum(a - b for a, b in pairs) / n; pos = sum(a > b for a, b in pairs); neg = sum(a < b for a, b in pairs)
    return {"mean": round(d, 3), "lo": round(ds[int(0.025 * B)], 3), "hi": round(ds[int(0.975 * B) - 1], 3), "lb1": round(ds[int(0.05 * B)], 3),
            "pos": pos, "neg": neg, "zero": n - pos - neg, "n": n}

def fmt(c): return f"{c['mean']:+.3f} [{c['lo']:+.3f}, {c['hi']:+.3f}] | {c['lb1']:+.3f} | {c['pos']}/{c['neg']}/{c['zero']} | {c['n']}"

def load_recs(pattern, model=None):
    out = []
    for f in glob.glob(pattern):
        for l in open(f, encoding="utf-8"):
            try: r = json.loads(l)
            except Exception: continue
            if "arm" in r and (model is None or r["model"] == model): out.append(r)
    return out

def spend(recs):
    c = 0.0
    for r in recs:
        for u in r.get("usage", []):
            p = price_for(r["model"], u); c += (u["in"] * p[0] + u["out"] * p[1] + u["cache_read"] * p[2] + u["cache_write"] * p[3]) / 1e6
    return round(c, 2)

def meta_for(ctxdir): return json.load(open(os.path.join(H, ctxdir, "contexts.json"), encoding="utf-8"))
def arm_of(m, a):
    am = m["arms"].get(a, {}); return arm_of(m, am["same_as"]) if "same_as" in am else a
def tok(m, a): return m["arms"][arm_of(m, a)].get("n_tokens_prompt")

R = {"generated": "2026-10-18", "notes": []}; md = ["# Verified results for the Phase 1-3 exploratory ablations (auto-generated by analysis/phase23.py)\n",
      "All numbers below are computed from the verdict records in harness/results-abl, harness/results-p2, harness/results-p2screen and harness/results-p3 and the arm metadata in harness/abl-*/ and harness/ablr-*/contexts.json. Paired contrasts use the instance-level percentile bootstrap (2,000 resamples, seed 2): mean difference, two-sided 95% interval, one-sided 95% lower bound (the preregistered decision bound), sign counts (+/−/0), n instances. ε = 0.05.\n"]

# ---------------- spend ----------------
p1 = load_recs(os.path.join(H, "results-abl", "*.jsonl")); p2 = load_recs(os.path.join(H, "results-p2", "*.jsonl")); p2s = load_recs(os.path.join(H, "results-p2screen", "*.jsonl")); p3 = load_recs(os.path.join(H, "results-p3", "*.jsonl"))
R["spend"] = {"phase1_results_abl": spend(p1), "phase2_results_p2": spend(p2), "phase2_screen": spend(p2s), "phase3_results_p3": spend(p3)}
R["spend"]["total_phases_1_3"] = round(sum(R["spend"].values()), 2)
R["samples"] = {"phase1": len(p1), "phase2": len(p2), "phase2_screen": len(p2s), "phase3": len(p3)}
by_model = collections.defaultdict(lambda: [0, 0.0])
for r in p1 + p2 + p2s + p3:
    by_model[r["model"]][0] += 1
    for u in r.get("usage", []):
        pr = price_for(r["model"], u); by_model[r["model"]][1] += (u["in"] * pr[0] + u["out"] * pr[1] + u["cache_read"] * pr[2] + u["cache_write"] * pr[3]) / 1e6
R["spend_by_model"] = {m: {"samples": v[0], "usd": round(v[1], 2)} for m, v in by_model.items()}
md += ["## Spend and sample counts (list prices, USD)\n", "| phase | samples | USD |", "|---|---|---|",
       f"| Phase 1 (results-abl, Haiku 5.5, 23 cli instances, k=20) | {len(p1)} | {R['spend']['phase1_results_abl']} |",
       f"| Phase 2 screen (results-p2screen, W at k=5) | {len(p2s)} | {R['spend']['phase2_screen']} |",
       f"| Phase 2 (results-p2: four models on 10 instances, plus leave-one-out at k=100) | {len(p2)} | {R['spend']['phase2_results_p2']} |",
       f"| Phase 3 (results-p3: screen k=20, Haiku k=50, Sonnet k=10 on 11 instances) | {len(p3)} | {R['spend']['phase3_results_p3']} |",
       f"| Total Phases 1-3 | {len(p1)+len(p2)+len(p2s)+len(p3)} | {R['spend']['total_phases_1_3']} |", "",
       "By model: " + "; ".join(f"{m}: {v['samples']} samples, ${v['usd']}" for m, v in sorted(R["spend_by_model"].items())) + ".",
       "The pilot (DOI 10.5281/zenodo.23307204) cost about $73 at list prices (erratum of 2026-10-12; the pilot paper states $61).\n"]

# ---------------- Phase 1 (copied from the frozen report) ----------------
rep1 = open(os.path.join(H, "results-abl", "ABLATION-REPORT.md"), encoding="utf-8").read()
keep = [l for l in rep1.split("\n") if l.startswith("|") or l.startswith("- ") or l.startswith("A1 now") or l.startswith("Instances with") or l.startswith("Instances where")]
md += ["## Phase 1 (2026-10-12): leave-one-dependency-out on the 23 valid pilot instances, Haiku 5.5, k=20, task-text rule of the original H5 paragraph\n",
       "Source: harness/results-abl/ABLATION-REPORT.md (frozen output of analysis/ablation.py). Rows reproduced verbatim:\n"] + [l for l in keep if "| instance |" not in l and not re.match(r"^\| [0-9a-f]{12} \|", l)] + [""]
R["phase1_report_excerpt"] = "\n".join(keep)

# ---------------- Phase 2 ----------------
p2sel = [l.split("\t") for l in open(os.path.join(H, "p2_selected.tsv"), encoding="utf-8").read().strip().split("\n")]
p2ids = [s[0] for s in p2sel]; p2ctx = {s[0]: s[1] for s in p2sel}; p2meta = {i: meta_for(p2ctx[i]) for i in p2ids}
scr = json.load(open(os.path.join(H, "p2_selected.json"), encoding="utf-8"))
R["phase2_screen"] = {"screened": len(scr), "selected": sum(x["selected"] for x in scr), "w_inexpressible": sum(not x["w_expressible"] for x in scr),
                      "by_repo": dict(collections.Counter((x["repo"], x["selected"]) for x in scr).items() and {f"{r}": [sum(1 for x in scr if x['repo']==r and x['selected']), sum(1 for x in scr if x['repo']==r)] for r in sorted({x['repo'] for x in scr}, key=str)})}
cells2 = collections.defaultdict(list)
for r in p2:
    if not r.get("api_error"): cells2[(r["model"], r["instance_id"], r["arm"])].append(bool(r.get("delta_pass")))
def rate2(m, i, a):
    v = cells2.get((m, i, arm_of(p2meta[i], a))); return sum(v) / len(v) if v else None
models2 = ["claude-haiku-5-5", "claude-haiku-4-5-20251001", "claude-sonnet-5-5", "claude-opus-5-5"]
k2 = {"claude-haiku-5-5": 100, "claude-haiku-4-5-20251001": 20, "claude-sonnet-5-5": 10, "claude-opus-5-5": 5}
md += ["## Phase 2 (2026-10-12/13): four models on the 10 instances selected by the W screen (W inexpressible and W < 0.8 at k=5)\n",
       f"Screen: {R['phase2_screen']['screened']} instances screened (22 cli, 10 caddy, 1 hugo, 1 restic, 1 golangci-lint), {R['phase2_screen']['w_inexpressible']} with W inexpressible, {R['phase2_screen']['selected']} selected (6 cli, 4 caddy). Task-text rule: 2026-10-12 amendment (selectors, code-span identifiers, import paths). Arms: W, A1, A1g, A1t for the dense models; A0, W, A1t for Opus 5.5. k per model: " + ", ".join(f"{m} {k}" for m, k in k2.items()) + ".\n",
       "### Per-instance pass rates (arm identical to another arm is shown with the rate of that arm)\n",
       "| instance | repo | deps | A1g kept | A1t kept | " + " | ".join(m.replace("claude-", "") for m in models2) + " |", "|---|---|---|---|---|" + "---|" * 4]
R["phase2_instances"] = []
for i in p2ids:
    m = p2meta[i]; row = {"instance": i, "repo": m["repo"], "deps": len(m["direct_deps"]), "a1g_kept": len(m["arms"]["A1g"].get("kept", [])), "a1t_kept": len(m["arms"]["A1t"].get("kept", []))}
    cells_txt = []
    for mo in models2:
        d = {a: rate2(mo, i, a) for a in ("A0", "W", "A1", "A1g", "A1t") if rate2(mo, i, a) is not None}; row[mo] = d
        cells_txt.append(" ".join(f"{a}={v:.2f}" for a, v in d.items()))
    R["phase2_instances"].append(row)
    md.append(f"| {i} | {m['repo']} | {row['deps']} | {row['a1g_kept']} | {row['a1t_kept']} | " + " | ".join(cells_txt) + " |")
md += ["", "### Paired contrasts\n", "| model | contrast | mean [95% CI] | one-sided LB | sign +/−/0 | n |", "|---|---|---|---|---|---|"]
R["phase2_contrasts"] = {}
for mo in models2:
    for x, y in (("A1t", "A1"), ("A1g", "A1"), ("W", "A1"), ("A1t", "W"), ("A0", "W")):
        pairs = [(rate2(mo, i, x), rate2(mo, i, y)) for i in p2ids if rate2(mo, i, x) is not None and rate2(mo, i, y) is not None]
        if len(pairs) < 2: continue
        c = boot(pairs); R["phase2_contrasts"][f"{mo}:{x}-{y}"] = c; md.append(f"| {mo} | {x} − {y} | {fmt(c)} |")
floor = {mo: sum(1 for i in p2ids if max((rate2(mo, i, a) or 0) for a in ("W", "A1", "A1g", "A1t", "A0")) < 0.1) for mo in models2}
R["phase2_floor_instances"] = floor
md += ["", "Instances whose best arm is below 0.1 (degenerate for a relative comparison): " + ", ".join(f"{m.replace('claude-','')} {v}/10" for m, v in floor.items()) + ".",
       "Median prompt tokens on the 10 instances: " + ", ".join(f"{a} {sorted(tok(p2meta[i], a) for i in p2ids)[5]:,}" for a in ("W", "A1", "A1g", "A1t")) + ".\n"]
# diagnostic: identifiers in passing patches (recorded 2026-10-13; see analysis note)
md += ["Diagnostic recorded 2026-10-13 (harness session, not a script output): in the three cells where context changed the outcome (caddy c8591a1e46e4 on Sonnet 5.5: A1 6/10, W 2/10, A1g 0/10, A1t 0/10; cli 2bcdfbb1ac02 on Haiku 5.5: A1 27/100, W 0/100; caddy 6727b2f3a92b on Haiku 5.5: W 44/100, A1 22/100, W = 158,565 tokens, A1 = 277,505 tokens) the passing patches introduced no code identifier that only the dependency documentation supplied; the only dependency-only tokens in passing patches were English words from comments.\n"]

# ---------------- LOO k=100 ----------------
loo = [l.split("\t") for l in open(os.path.join(H, "p2_loo_selected.tsv"), encoding="utf-8").read().strip().split("\n")]
md += ["## Leave-one-dependency-out at k=100 (Haiku 5.5; Phase 2 stage 6, restricted on 2026-10-13 to the three instances with A1 ≥ 0.1)\n",
       "Difference = pass(A1 minus group) − pass(A1). Null reference: all cells of an instance drawn from one pooled rate at k=100, 2,000 simulations, count of removals with |difference| > 0.05.\n"]
R["loo"] = {}
for i, c, w in loo:
    m = meta_for(c); cc = collections.defaultdict(list)
    for r in p2:
        if r["instance_id"] == i and r["model"] == "claude-haiku-5-5" and not r.get("api_error"): cc[r["arm"]].append(bool(r.get("delta_pass")))
    base = sum(cc["A1"]) / len(cc["A1"]); rows = []
    for gi, g in enumerate(m["groups"]):
        v = cc.get(f"A1-{gi:02d}")
        if v: rows.append({"removed": [x.split("/")[-1] for x in g], "pass": round(sum(v) / len(v), 2), "diff": round(sum(v) / len(v) - base, 2), "n": len(v)})
    # null
    rnd = random.Random(3); allc = [cc["A1"]] + [cc[f"A1-{gi:02d}"] for gi in range(len(m["groups"])) if cc.get(f"A1-{gi:02d}")]
    p = sum(sum(x) for x in allc) / sum(len(x) for x in allc); sims = []
    for _ in range(B):
        b = sum(rnd.random() < p for _ in range(100)) / 100; sims.append(sum(abs(sum(rnd.random() < p for _ in range(100)) / 100 - b) > 0.05 for _ in rows))
    sims.sort(); obs = sum(abs(r["diff"]) > 0.05 for r in rows)
    R["loo"][i] = {"A1": round(base, 2), "W": round(sum(cc["W"]) / len(cc["W"]), 2), "n_A1": len(cc["A1"]), "groups": rows, "obs_over_eps": obs, "null_mean": round(sum(sims) / B, 1), "null_95": [sims[int(0.025 * B)], sims[int(0.975 * B) - 1]],
                   "a1g_kept": [x.split("/")[-1] for x in m["arms"]["A1g"].get("kept", [])], "a1t_kept": [x.split("/")[-1] for x in m["arms"]["A1t"].get("kept", [])], "tokens_A1": tok(m, "A1"), "tokens_W": tok(m, "W")}
    md += [f"### {i} ({m['repo']}): A1 = {base:.2f} (n={len(cc['A1'])}), W = {R['loo'][i]['W']:.2f}; A1 tokens {tok(m,'A1'):,}, W tokens {tok(m,'W'):,}; gold-referenced kept {R['loo'][i]['a1g_kept']}; task-referenced kept {R['loo'][i]['a1t_kept']}\n",
           "| removed group | pass | difference | n |", "|---|---|---|---|"] + [f"| {', '.join(r['removed'])} | {r['pass']:.2f} | {r['diff']:+.2f} | {r['n']} |" for r in sorted(rows, key=lambda r: r["diff"])] + \
          [f"\nRemovals with |difference| > 0.05: {obs} of {len(rows)}; null reference {R['loo'][i]['null_mean']} [{R['loo'][i]['null_95'][0]}, {R['loo'][i]['null_95'][1]}].\n"]
# Phase 2 A1g for 2bcd for the non-additivity statement
md += [f"Phase 2 cell for cli 2bcdfbb1ac02 on Haiku 5.5 at k=100: W {rate2('claude-haiku-5-5','cli__cli-2bcdfbb1ac02','W'):.2f}, A1 {rate2('claude-haiku-5-5','cli__cli-2bcdfbb1ac02','A1'):.2f}, A1g = A1t (keeps queries and iostreams) {rate2('claude-haiku-5-5','cli__cli-2bcdfbb1ac02','A1g'):.2f}.\n"]

# ---------------- Phase 3 ----------------
p3sel = [l.split("\t") for l in open(os.path.join(H, "p3_selected_existing.tsv"), encoding="utf-8").read().strip().split("\n")]
p3ids = [s[0] for s in p3sel]; p3ctx = {s[0]: s[1] for s in p3sel}; p3meta = {i: meta_for(p3ctx[i]) for i in p3ids}
scr3 = json.load(open(os.path.join(H, "p3_selected_existing.json"), encoding="utf-8"))
R["phase3_screen"] = {"screened": len(scr3), "selected_incl_hugo": sum(x["selected"] for x in scr3), "selected_run": len(p3ids)}
cells3 = collections.defaultdict(list); cells3_post = collections.defaultdict(list)
for r in p3:
    if r.get("api_error"): continue
    cells3[(r["model"], r["instance_id"], r["arm"])].append(bool(r.get("delta_pass")))
    if not (r["model"] == "claude-haiku-5-5" and r["arm"] in ("W", "A1") and r["sample"] < 20): cells3_post[(r["model"], r["instance_id"], r["arm"])].append(bool(r.get("delta_pass")))
def rate3(m, i, a, post=False):
    v = (cells3_post if post else cells3).get((m, i, arm_of(p3meta[i], a))); return sum(v) / len(v) if v else None
HK, SN = "claude-haiku-5-5", "claude-sonnet-5-5"; arms3 = ["W", "Wd", "A1", "A1r", "Wdr", "Wpad", "A1t"]
md += ["## Phase 3 (2026-10-13/14): declaration-level arms and matched padding on the 11 instances selected by the k=20 W/A1 screen (either rate in [0.1, 0.9]); hugo instance selected but dropped (unrunnable)\n",
       f"Screen: {len(scr3)} instances screened with W and A1 at k=20 on Haiku 5.5; {R['phase3_screen']['selected_incl_hugo']} selected including gohugoio/hugo c9f6e4d4abc3, which was dropped on 2026-10-14 (its single instance produced a 182 GB build cache); {len(p3ids)} run (8 cli, 3 caddy). Haiku 5.5 k=50 on W, A1, A1t, Wd, A1r, Wdr, Wpad (W and A1 continue the k=20 screen samples); Sonnet 5.5 k=10 on W, A1, Wd, A1r, Wdr, Wpad. 17 records written while the disk was full on 2026-10-14 were purged with their cached-verdict dependants and re-sampled.\n",
       "Arms: Wd = declarations of W reachable through the type-checked reference graph from identifiers in the fail-to-pass tests and task-text code spans/selectors (imports and package clauses kept, omitted declarations marked); A1r = full W plus only the dependency declarations W references, rendered without bodies; Wdr = the slice plus the dependency declarations the slice references; Wpad = W preceded by inert same-module padding (pilot pool) matched to A1's prompt tokens.\n",
       "### Per-instance: prompt tokens and pass rates (Haiku 5.5 k=50; Sonnet 5.5 k=10). '=' marks an arm byte-identical to another arm.\n",
       "| instance | repo | tok W | tok Wd | tok A1 | tok A1r | tok Wdr | tok Wpad | slice decls | dep decls (slice/all) | " + " | ".join("H " + a for a in arms3) + " | " + " | ".join("S " + a for a in arms3[:6]) + " |",
       "|---|---|---|---|---|---|---|---|---|---|" + "---|" * 13]
R["phase3_instances"] = []
for i in p3ids:
    m = p3meta[i]; sm = m.get("struct_meta", {}); row = {"instance": i, "repo": m["repo"], "tokens": {a: tok(m, a) for a in arms3}, "slice": f"{sm.get('n_selected')}/{sm.get('n_w_decls')}", "deprefs": f"{sm.get('n_dep_refs_sel')}/{sm.get('n_dep_refs_all')}",
                                                             "haiku": {a: rate3(HK, i, a) for a in arms3}, "haiku_post": {a: rate3(HK, i, a, True) for a in ("W", "A1")}, "sonnet": {a: rate3(SN, i, a) for a in arms3[:6]}, "alias": {a: arm_of(m, a) for a in arms3}}
    R["phase3_instances"].append(row)
    def cell(mo, a):
        v = rate3(mo, i, a); return ("–" if v is None else f"{v:.2f}") + ("=" if arm_of(m, a) != a else "")
    md.append(f"| {i} | {m['repo']} | {tok(m,'W'):,} | {tok(m,'Wd'):,} | {tok(m,'A1'):,} | {tok(m,'A1r'):,} | {tok(m,'Wdr'):,} | {tok(m,'Wpad'):,} | {row['slice']} | {row['deprefs']} | " + " | ".join(cell(HK, a) for a in arms3) + " | " + " | ".join(cell(SN, a) for a in arms3[:6]) + " |")
md += ["", "### Paired contrasts, Haiku 5.5 (W and A1 from post-screen samples only, n=30 per instance; other arms n=50)\n", "| contrast | mean [95% CI] | one-sided LB | sign +/−/0 | n | median token ratio |", "|---|---|---|---|---|---|"]
R["phase3_contrasts"] = {}
pairs_list = (("Wd", "W"), ("A1r", "A1"), ("Wdr", "A1"), ("Wdr", "W"), ("A1", "W"), ("Wpad", "W"), ("Wpad", "A1"), ("A1r", "W"), ("A1t", "A1"), ("A1t", "W"))
for x, y in pairs_list:
    pairs = [(rate3(HK, i, x, True), rate3(HK, i, y, True)) for i in p3ids]; pairs = [q for q in pairs if None not in q]; c = boot(pairs); tr = sorted(tok(p3meta[i], x) / tok(p3meta[i], y) for i in p3ids)[len(p3ids) // 2]
    c["token_ratio_median"] = round(tr, 2); R["phase3_contrasts"][f"haiku_post:{x}-{y}"] = c; md.append(f"| {x} − {y} | {fmt(c)} | {tr:.2f} |")
md += ["", "### Paired contrasts, Haiku 5.5 (all samples, W and A1 n=50 including the 20 screen samples)\n", "| contrast | mean [95% CI] | one-sided LB | sign +/−/0 | n |", "|---|---|---|---|---|"]
for x, y in pairs_list:
    pr_ = [q for q in [(rate3(HK, i, x), rate3(HK, i, y)) for i in p3ids] if None not in q]; c = boot(pr_); R["phase3_contrasts"][f"haiku_all:{x}-{y}"] = c; md.append(f"| {x} − {y} | {fmt(c)} |")
md += ["", "### Paired contrasts, Sonnet 5.5 (k=10, no screen samples)\n", "| contrast | mean [95% CI] | one-sided LB | sign +/−/0 | n |", "|---|---|---|---|---|"]
for x, y in pairs_list:
    pr_ = [q for q in [(rate3(SN, i, x), rate3(SN, i, y)) for i in p3ids] if None not in q]
    if not pr_: R["phase3_contrasts"][f"sonnet:{x}-{y}"] = None; md.append(f"| {x} − {y} | not run on Sonnet 5.5 |"); continue
    c = boot(pr_); R["phase3_contrasts"][f"sonnet:{x}-{y}"] = c; md.append(f"| {x} − {y} | {fmt(c)} |")
ceil_s = sum(1 for i in p3ids if all((rate3(SN, i, a) or 0) >= 0.999 for a in ("W", "A1")))
nd = {mo: sum(1 for i in p3ids if max((rate3(mo, i, a) or 0) for a in arms3[:6]) >= 0.1) for mo in (HK, SN)}
R["phase3_nondegenerate"] = nd; R["phase3_sonnet_ceiling_W_and_A1"] = ceil_s
med = {a: sorted(tok(p3meta[i], a) for i in p3ids)[len(p3ids) // 2] for a in arms3[:6]}
R["phase3_median_tokens"] = med
md += ["", f"Non-degenerate instances (best arm ≥ 0.1): Haiku {nd[HK]}/11, Sonnet {nd[SN]}/11. Sonnet instances with both W and A1 at 1.00: {ceil_s}/11.",
       "Median prompt tokens: " + ", ".join(f"{a} {v:,}" for a, v in med.items()) + ".",
       "Instances where Wd is byte-identical to W (every declaration reachable): " + ", ".join(i for i in p3ids if arm_of(p3meta[i], "Wd") == "W") + ".\n"]
# Wpad matching per instance (pad pool may be exhausted below A1's size)
wp = []
for i in p3ids:
    m = p3meta[i]; pm = m.get("pad_meta", {}).get("Wpad", {}); wp.append(f"{i[-12:]} Wpad {tok(m,'Wpad'):,} vs A1 {tok(m,'A1'):,} ({len(pm.get('pad_pkgs', []))} padding packages from the same-module pool)")
md += ["Wpad token matching per instance (target = A1's prompt tokens; the inert padding is drawn from same-module packages outside W, its dependencies and dependents, in a fixed hash order; package names are recorded in each contexts.json under pad_meta): " + "; ".join(wp) + ".\n"]
R["phase3_wpad_matching"] = {i: {"wpad_tokens": tok(p3meta[i], "Wpad"), "a1_tokens": tok(p3meta[i], "A1"), "n_pad_pkgs": len(p3meta[i].get("pad_meta", {}).get("Wpad", {}).get("pad_pkgs", []))} for i in p3ids}
# screen->post drift per instance
md += ["Per-instance W and A1 on Haiku 5.5, screen (k=20) → post-screen (n=30): " + "; ".join(f"{i[-12:]} W {sum(cells3[(HK,i,'W')][:20])/20:.2f}→{rate3(HK,i,'W',True):.2f}, A1 {sum(cells3[(HK,i,'A1')][:20])/20:.2f}→{rate3(HK,i,'A1',True):.2f}" for i in p3ids) + ".\n"]

# ---------------- mining and instance pool ----------------
inst_files = glob.glob(os.path.join(H, "instances", "*.json")); pool = collections.Counter()
for f in inst_files:
    b = os.path.basename(f)
    if b.startswith("_template"): continue
    pool[b.rsplit("-", 1)[0]] += 1
R["instance_pool"] = dict(pool)
md += ["## Instance pool\n", "Valid mined instances on disk by repository prefix: " + ", ".join(f"{k} {v}" for k, v in sorted(pool.items())) + ". cli__cli includes the 24 pilot instances (one invalid: empty task text) and earlier template/test instances; see harness/instances/rejected.jsonl for every examined commit and its rejection reason. Mining windows: commits since 2026-06-01; caddy 159 first-parent commits, hugo 240, zap 13 (none valid); relaxed limits (≤4 packages, ≤300 changed lines) on restic and golangci-lint on 2026-10-14 produced no new valid instance; relaxed mining of caddy, hugo and cli was stopped by the disk incident and not rerun.\n"]

# ---------------- integrity notes ----------------
md += ["## Data-integrity events (all recorded in preregistration.md §8)\n",
       "- 2026-10-12 Phase 1: build-environment fault invalidated verdicts for 4,456 samples; 4,409 re-verified from stored responses with a patch-hash equality check, 44 re-sampled; the faulty aggregate was seen before repair.",
       "- 2026-10-12/13 Phase 2: disk-full interruption contaminated the hugo baseline and 17 mining rejections (purged and re-examined); docker/cli replaced by restic and golangci-lint (no root go.mod); instance cli bd81afda9ab6 absent (arms failed to build).",
       "- 2026-10-13 Phase 2 stage 6: leave-one-out restricted to three responsive instances; completed samples on floor instances kept.",
       "- 2026-10-14 Phase 3: shared Go build cache reached about 150 GB (per-patch relinking of test binaries); lanes restarted with per-lane caches; hugo dropped; 17 disk-error records purged with dependants and re-sampled; originals retained by the author.\n"]
json.dump(R, open(os.path.join(OUT, "RESULTS.json"), "w", encoding="utf-8"), indent=1)
open(os.path.join(OUT, "RESULTS.md"), "w", encoding="utf-8").write("\n".join(md))
print("\n".join(md))
